import React, { useState, useEffect } from "react"
import axios from 'axios'
import "./Home.scss"
import GroupCard from '../../components/GroupCard/GroupCard';
import AddNewGroup from "../../components/AddNewGroup/AddNewGroup";
import { Toaster, toast } from "sonner";

const Home = () => {
  const [groups, setGroups] = useState([])
  const [currentPage, setCurrentPage] = useState(1)
  const [groupsPerPage] = useState(3)

  const getGroupDesc = async () => {
    try {
      const groupData = await axios.get('http://localhost:8800/groupdesc')
      setGroups(groupData.data)
    } catch (error) {
      console.error('Failed to fetch data', error)
    }
}

  const addGroup = async (group) => {
    try {
      // Add the new group
      await axios.post("http://localhost:8800/group", group);
      toast.success(`Successfully added ${group.groupName}`)
      getGroupDesc()
    } catch (error) {
      console.error('Failed to add group:', error);
      toast.error('Failed to add group')
    }
  }

  const handleRemoveClick = async (groupName) => {
    try {
      await axios.delete(`http://localhost:8800/group/${groupName}`)
      fetchGroups(); // Optionally fetch groups again after deletion
    } catch (error) {
      console.error(`Failed to delete group: ${groupName}`, error)
    }
  }

  useEffect(() => {
    getGroupDesc()
  }, [groups])
  
  const handlePageChange = (pageNumber) => {
    setCurrentPage(pageNumber)
  }

  const indexOfLastGroup = currentPage * groupsPerPage
  const indexOfFirstGroup = indexOfLastGroup - groupsPerPage
  const currentGroups = groups.slice(indexOfFirstGroup, indexOfLastGroup)

  return (
    <div className="main-container">
      <div className="dashboard-container">
        <div className="home-top-container">
          <div className="section-name-container">
            <h1 className="section-name">Dashboard</h1>
          </div>
          <AddNewGroup getGroupDesc={getGroupDesc} />
        </div>
        <div className="home-body-container">
          <GroupCard
            groups={currentGroups}
            currentPage={currentPage}
            groupsPerPage={groupsPerPage}
            handlePageChange={handlePageChange}
          />
          <div className="pagination-container">
            {Array.from({ length: Math.ceil(groups.length / groupsPerPage) }).map(
              (_, index) => (
                <button
                  key={index + 1}
                  className={`pagination-button ${
                    currentPage === index + 1 ? "active" : ""
                  }`}
                  onClick={() => handlePageChange(index + 1)}
                >
                  {index + 1}
                </button>
              )
            )}
          </div>
        </div>
      </div>
    </div>
  )
}

export default Home
